@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&display=swap');
:root{--ink:#f4f3e9;--muted:#a9b5ad;--lime:#d8f36a;--deep:#071b15;--line:rgba(235,245,226,.13)}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#061711;color:var(--ink);font-family:'DM Sans',sans-serif}body{background:radial-gradient(ellipse at 50% 34%,#173a2b 0,#0a241a 47%,#061711 86%);min-height:100vh}.app-shell{width:min(1200px,calc(100% - 54px));margin:auto;padding:20px 0 16px}.topbar{height:56px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);margin-bottom:26px}.brand{display:flex;align-items:center;gap:10px;color:var(--ink);text-decoration:none;font-size:14px;font-weight:800;letter-spacing:1px;line-height:1}.brand-mark{width:34px;height:34px;border:1px solid #6c8c42;border-radius:50%;display:grid;place-items:center;color:var(--lime);font-size:19px}.brand b{color:var(--lime)}.brand small{display:block;color:#9bad9e;font:9px 'DM Mono',monospace;letter-spacing:1.3px;margin-top:5px}.live-pill{border:1px solid rgba(216,243,106,.22);color:#c6d6ad;border-radius:20px;padding:7px 12px;font:9px 'DM Mono',monospace;letter-spacing:1.4px}.live-pill i,.round-dot,.clock-dot{display:inline-block;width:6px;height:6px;background:var(--lime);border-radius:50%;margin-right:7px;box-shadow:0 0 8px #d8f36a}.sound-toggle{border:0;background:none;color:#c1cec1;font:11px 'DM Mono',monospace;letter-spacing:1px;cursor:pointer}.sound-toggle span{margin-left:5px}.match-wrap{max-width:1080px;margin:0 auto}.match-head{display:flex;justify-content:space-between;align-items:end;margin:0 4px 14px}.eyebrow,.round-tag{font:10px 'DM Mono',monospace;color:#9cac9f;letter-spacing:1.7px}.eyebrow span{color:var(--lime);padding:0 5px}h1{font:700 29px 'Barlow Condensed',sans-serif;letter-spacing:1.2px;margin:5px 0 0}h1 em,.overlay-card h2 em{font-style:normal;color:var(--lime)}.round-tag{margin-bottom:5px;font-size:9px}.round-dot{width:5px;height:5px}.tag-divider{color:#58685d;padding:0 8px}.scoreboard{height:80px;background:#10291e;border:1px solid #2b4935;border-bottom:0;display:grid;grid-template-columns:1fr 180px 1fr;align-items:center;padding:0 25px}.team{display:flex;align-items:center;gap:12px}.team-away{justify-content:flex-end;text-align:right}.team strong{display:block;font:700 16px 'Barlow Condensed',sans-serif;letter-spacing:1.3px}.team small{display:block;font:9px 'DM Mono',monospace;color:#9eaf9f;letter-spacing:1.4px;margin-top:4px}.team-crest{width:42px;height:42px;display:grid;place-items:center;font:800 14px 'Barlow Condensed',sans-serif;clip-path:polygon(50% 0,95% 16%,88% 73%,50% 100%,12% 73%,5% 16%);color:#f9f1cc}.home-crest{background:linear-gradient(90deg,#0879bf 0 42%,#eacb3f 42% 60%,#0879bf 60%)}.away-crest{color:#fff;background:repeating-linear-gradient(0deg,#e7e4dc 0 5px,#d72839 5px 10px)}.score-center{text-align:center}.scoreline{font:700 37px 'Barlow Condensed',sans-serif;letter-spacing:2px;line-height:1}.scoreline i{font-style:normal;font-size:23px;color:#859588;padding:0 10px}.match-clock{margin-top:5px;font:10px 'DM Mono',monospace;color:#d0d9ce;letter-spacing:1px}.match-clock b{margin-left:9px;color:#96a49a;font-size:9px}.clock-dot{width:5px;height:5px;margin-right:5px}.stadium-frame{position:relative;overflow:hidden;border:1px solid #2b4935;background:#0b2117;box-shadow:0 22px 65px #020d09a6}.stadium-frame canvas{display:block;width:100%;height:auto;aspect-ratio:5/3;max-height:62vh;object-fit:contain;touch-action:none}.canvas-vignette{position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 110px #06120d75,inset 0 0 0 1px #ffffff08}.canvas-hud{position:absolute;top:15px;left:18px;right:18px;display:flex;justify-content:space-between;pointer-events:none;color:#eef3e7;font:9px 'DM Mono',monospace;letter-spacing:1px;text-shadow:0 1px 5px #000}.weather b{color:#f1d66a;font-size:13px}.weather i{font-style:normal;color:#a6c76b;padding:0 4px}.hud-right{color:#d2dfca}.hud-right b{color:var(--lime)}.center-overlay{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:linear-gradient(90deg,#06150fbb,#07171073 51%,#06150fcc);backdrop-filter:blur(2px);transition:opacity .25s}.center-overlay.hidden,.hidden{display:none}.overlay-card{width:min(440px,90%);padding:30px 36px 26px;background:#10291eeb;border:1px solid #63804575;box-shadow:0 18px 70px #0009;text-align:center;position:relative}.overlay-card:before,.overlay-card:after{content:'';position:absolute;width:18px;height:18px;border-color:var(--lime);border-style:solid}.overlay-card:before{top:-1px;left:-1px;border-width:1px 0 0 1px}.overlay-card:after{bottom:-1px;right:-1px;border-width:0 1px 1px 0}.mini-label{display:flex;align-items:center;justify-content:center;gap:9px;color:#c4d2bf;font:9px 'DM Mono',monospace;letter-spacing:2px}.mini-label span{width:20px;height:1px;background:#829768}.overlay-card h2{font:800 46px/.88 'Barlow Condensed',sans-serif;letter-spacing:1px;margin:17px 0 11px}.overlay-card p{color:#aab8a8;font-size:12px;margin:0 0 19px}.play-button{height:47px;width:100%;padding:0 16px 0 22px;background:var(--lime);color:#142218;border:0;display:flex;align-items:center;justify-content:space-between;font:800 11px 'DM Sans',sans-serif;letter-spacing:1.25px;cursor:pointer;transition:transform .15s,background .15s}.play-button:hover{background:#e5ff83;transform:translateY(-2px)}.play-button b{font-size:22px;font-weight:500}.team-selects{display:flex;justify-content:space-between;align-items:center;margin-top:15px;gap:8px;color:#8f9e8e;font:8px 'DM Mono',monospace;letter-spacing:.6px}.team-selects label{display:flex;align-items:center;gap:6px}.team-selects select{background:#193627;color:#d8e6d2;border:1px solid #4a6342;padding:5px 4px;font:8px 'DM Mono',monospace;max-width:158px}.pause-card{width:min(390px,90%)}.pause-card h2{font-size:43px}.goal-flash{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);color:#e5ff83;font:900 clamp(42px,8vw,82px)/.8 'Barlow Condensed',sans-serif;text-align:center;letter-spacing:3px;text-shadow:0 5px 32px #000;pointer-events:none;animation:goalPop .45s ease-out}.goal-flash small{display:block;font:700 11px 'DM Mono',monospace;letter-spacing:3px;margin-top:14px;color:#fff}.goal-flash.hidden{display:none}@keyframes goalPop{from{transform:translate(-50%,-50%) scale(.5);opacity:0}to{transform:translate(-50%,-50%) scale(1);opacity:1}}.game-footer{height:49px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line)}.controls{display:flex;align-items:center;gap:17px}.key-group{display:flex;align-items:center;gap:3px}.key-group kbd{height:19px;min-width:19px;padding:2px 5px;border:1px solid #536856;border-bottom-width:2px;border-radius:3px;background:#173024;color:#d8e5d6;text-align:center;font:9px 'DM Mono',monospace}.key-group kbd.wide{min-width:57px}.key-group span{margin-left:5px;color:#99a999;font:8px 'DM Mono',monospace;letter-spacing:.6px}.footer-note{color:#9aab9a;font:8px 'DM Mono',monospace;letter-spacing:1px}.spark{color:var(--lime);font-size:13px;padding-right:5px}.bottomline{max-width:1080px;margin:14px auto 0;display:flex;justify-content:space-between;color:#637667;font:8px 'DM Mono',monospace;letter-spacing:1.2px}.bottomline b{color:#d86a60}.mobile-controls{display:none}
@media(max-width:700px){.app-shell{width:calc(100% - 22px);padding-top:10px}.topbar{height:48px;margin-bottom:16px}.brand{font-size:12px}.brand-mark{width:29px;height:29px}.brand small{font-size:7px}.live-pill{font-size:8px;padding:6px 8px}.sound-toggle{font-size:0}.sound-toggle:first-letter{font-size:17px}.sound-toggle span{display:none}.match-head{align-items:center;margin-bottom:10px}.eyebrow{font-size:8px}h1{font-size:23px}.round-tag{font-size:0}.round-tag .round-dot{margin-right:0}.round-tag .tag-divider{display:none}.scoreboard{height:66px;grid-template-columns:1fr 84px 1fr;padding:0 10px}.team{gap:7px}.team-crest{width:32px;height:34px;font-size:11px}.team strong{font-size:11px;letter-spacing:.5px}.team small{font-size:7px;margin-top:2px}.scoreline{font-size:29px}.scoreline i{font-size:18px;padding:0 5px}.match-clock{font-size:8px}.stadium-frame canvas{aspect-ratio:4/3;max-height:none}.canvas-hud{top:9px;left:9px;right:9px;font-size:7px}.weather{max-width:50%}.hud-right{font-size:7px}.overlay-card{padding:21px 20px 18px;width:min(390px,92%)}.overlay-card h2{font-size:39px;margin:13px 0 8px}.overlay-card p{font-size:11px;margin-bottom:13px}.play-button{height:42px;font-size:10px}.team-selects{margin-top:10px;font-size:7px}.team-selects select{font-size:7px;max-width:137px}.game-footer{height:auto;min-height:42px}.controls{gap:8px}.key-group{gap:2px}.key-group kbd{min-width:17px;height:17px;font-size:8px;padding:2px 4px}.key-group kbd.wide{min-width:43px}.key-group span{font-size:0;margin:0}.footer-note{font-size:0}.footer-note .spark{font-size:13px}.bottomline{font-size:7px;margin-top:9px}.mobile-controls{display:flex;justify-content:space-between;align-items:center;padding:9px 5px 0}.dpad{display:grid;grid-template-columns:34px 34px 34px;grid-template-rows:32px 32px;gap:3px}.dpad button,.mobile-actions button{border:1px solid #557049;background:#173326dd;color:#e4eedb;border-radius:5px;touch-action:none;user-select:none;font:14px 'DM Sans',sans-serif}.dpad button:first-child{grid-column:2}.dpad button:nth-child(2){grid-column:1;grid-row:2}.dpad button:nth-child(3){grid-column:2;grid-row:2}.dpad button:nth-child(4){grid-column:3;grid-row:2}.mobile-actions{display:flex;gap:9px}.mobile-actions button{height:48px;padding:0 17px;font:800 9px 'DM Sans',sans-serif;letter-spacing:1px}.mobile-actions button:last-child{background:var(--lime);color:#172317;border-color:#e3fc87}.mobile-actions button.active,.dpad button.active{filter:brightness(1.45);transform:scale(.96)}}
@media(max-width:370px){.team strong{font-size:9px}.team-crest{width:27px;height:30px}.scoreboard{grid-template-columns:1fr 70px 1fr}.team-selects{align-items:flex-start;flex-direction:column}.team-selects label{max-width:100%}.controls{gap:5px}}

